'use strict'

/**
 * 被管服务样例：一个 http 服务。
 *
 * 环境变量：
 *   APP1_PORT    监听端口，默认 3456。测试台会显式传入，避免多个用例撞端口。
 *   APP1_RSS_MB  启动后额外占用的内存（MB），默认 0。用于触发 limit.maxrss。
 *
 * 参数：
 *   --strong     故意吞掉 SIGINT/SIGTERM/SIGABRT，用来验证 cdpc 的
 *                「优雅停机超时后 SIGKILL 兜底」是否真的兜得住。
 */

const http = require('http')

const PORT = parseInt(process.env.APP1_PORT || '3456', 10)
const RSS_MB = parseInt(process.env.APP1_RSS_MB || '0', 10)

if (process.argv.indexOf('--strong') > 0) {
  ;['SIGINT', 'SIGTERM', 'SIGABRT'].forEach(x => {
    process.on(x, sig => {
      console.log(process.pid, '接收到信号', sig, ', 不会退出')
    })
  })
}

const server = http.createServer((req, res) => {
  req.on('data', chunk => {})

  req.on('end', () => {
    res.end(`success ${req.url}`)
  })
})

/**
 * 端口被占时必须**非零退出**。
 *
 * 早先这里没有 error 处理：EADDRINUSE 只是打一条 unhandled error，进程仍然活着，
 * 于是 restart:'always' 会一直重启一个永远起不来的服务，日志被上百条同样的
 * 堆栈刷满，真正的原因（端口被别人占了）反而看不出来。
 */
server.on('error', err => {
  if (err.code === 'EADDRINUSE') {
    console.error(`${process.pid} 端口 ${PORT} 已被占用，退出。`
      + `排查：ss -ltnp | grep ${PORT}`)
    process.exit(3)
  }

  console.error(`${process.pid} server error:`, err.message)
  process.exit(4)
})

server.listen(PORT, '0.0.0.0', () => {
  console.log(process.pid, `server listen ${PORT}`, process.argv)
})

process.on('message', (msg) => {
  console.log('web app', msg)
})

if (process.send) {
  process.send({pid: process.pid})
}

if (RSS_MB > 0) {
  // 挂在全局上防止被 GC 回收，否则 rss 观测不到
  process.rss = Buffer.alloc(RSS_MB * 1024 * 1024, 'x')
  console.log(`${process.pid} 额外占用 ${RSS_MB}MB`, process.memoryUsage().rss)
}
